.streak-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.75em;
  padding: 0.4em 0.9em;
  border-radius: 999px;
  background: var(--myelin-wash);
  color: var(--ink);
  font: inherit;
  font-size: clamp(0.875rem, 1.2vw, 1.05rem);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.streak-badge__label {
  font-weight: 600;
}

.streak-badge__track {
  display: block;
  width: clamp(4rem, 8vw, 7rem);
  height: 0.4em;
  border-radius: 999px;
  background: var(--slide);
  overflow: hidden;
}

.streak-badge__fill {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--myelin);
  transition: width 400ms ease;
}

:root[data-motion="reduce"] .streak-badge__fill {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .streak-badge__fill {
    transition: none;
  }
}
